code_examples.vulnerable:
#include <stdio.h>
int factorial(int i)
{
    // 재귀함수 탈출 조건을 설정하지 않아 무한루프가 된다.
    return i * factorial(i - 1);
}
int main()
{
    int num = 5;
    int result = factorial(num);
    printf("%d! : %d\n", num, result);
    return 0;
}

code_examples.safe:
#include <stdio.h>

int factorial(int i)
{
    // 재귀함수 사용 시에는 아래와 같이 탈출 조건을 사용해야 한다.
    if (i <= 1) {
        return 1;
    }
    return i * factorial(i - 1);
}

int main()
{
    int num = 5;
    int result = factorial(num);
    printf("%d! : %d\n", num, result);
    return 0;
}
